def element_to_dict(element):
    """
    Recursively converts an XML element to a dictionary.
    """
    d = {}

    # Handle attributes
    if element.attrib:
        for k, v in element.attrib.items():
            d[f"@{k}"] = v

    # Handle text content
    if element.text:
        text = element.text.strip()
        if text:
            if d:
                d['#text'] = text
            else:
                d = {'#text': text}

    # Handle children
    children = {}
    for child in element:
        child_dict = element_to_dict(child)
        if child.tag in children:
            if isinstance(children[child.tag], list):
                children[child.tag].append(child_dict)
            else:
                children[child.tag] = [children[child.tag], child_dict]
        else:
            children[child.tag] = child_dict

    if children:
        d.update(children)

    return d

