def sorted_prime_factors(numbers: list):
    """
    Returns a list of prime factors sorted.
    >>> sorted_prime_factors([50, 21, 8, 2, 32, 3, 90, 0, 123])
    [[2, 5, 5], [3, 7], [2, 2, 2], [2], [2, 2, 2, 2, 2], [3], [2, 3, 3, 5], [], [3, 41]]
    """
    def prime_factorization(n):
        factors = []
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.append(d)
                n //= d
            d += 1
        if n > 1:
            factors.append(n)
        return factors

    result = []
    for number in numbers:
        if number == 0:
            result.append([])
        else:
            result.append(sorted(prime_factorization(number)))
    return result
